interface EntityMapper<E, C, R> {
  E toEntity(ResultSet rs) throws SQLException;
  void bindParameters(PreparedStatement ps, E entity) throws SQLException;
  E fromCreateRequest(C request);
  R toDto(E entity);
}
static <E,C,R> R create(Connection conn, String sql, C request, EntityMapper<E,C,R> mapper) throws SQLException {
  E entity = mapper.fromCreateRequest(request);
  try (PreparedStatement ps = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
    mapper.bindParameters(ps, entity);
    ps.executeUpdate();
    // odczytaj generated id, zbuduj finalna encje
  }
  return mapper.toDto(entity);
}

static Product insertAndReturnEntity(Connection conn, CreateProductRequest req) throws SQLException {
  Product toInsert = ProductMapper.fromCreateRequest(req);
  try (PreparedStatement ps = conn.prepareStatement("INSERT INTO products (name, price) VALUES (?,?)", Statement.RETURN_GENERATED_KEYS)) {
    ProductMapper.bindParameters(ps, toInsert);
    ps.executeUpdate();
    try (ResultSet keys = ps.getGeneratedKeys()) { keys.next(); return new Product(keys.getLong(1), toInsert.name(), toInsert.price()); }
  }
}

